import Paragraph from './Paragraph.vue';

export default {
  components: {
    Paragraph,
  },
  props: {
    formInfos: Array,
  },
  data: function() {
    let formdata = [];

    this.formInfos.map(forminfo => {
      var data = '';

      switch (forminfo.type) {
        case "select":
        case "radio":
          data = forminfo.selection[0].value;
          break;
      }

      formdata[forminfo.name] = data;
    });

    return {
      formdata: formdata,
      currentPath: '',
      admissionYesDates: ["20-12-2021", "24-1-2022", "22-2-2022", "21-3-2022",  "18-4-2022", "16-5-2022", "13-6-2022", "11-7-2022", "8-8-2022", "6-9-2022", "3-10-2022", "31-10-2022", "28-11-2022", "3-1-2023"],
      admissionNoDates: ["20-12-2021", "3-1-2022", "10-1-2022", "18-1-2022", "24-1-2022", "31-1-2022", "7-2-2022", "14-2-2022", "22-2-2022", "28-2-2022", "7-3-2022", "14-3-2022", "21-3-2022", "28-3-2022", "4-4-2022", "11-4-2022", "18-4-2022", "25-4-2022", "2-5-2022", "9-5-2022", "16-5-2022", "23-5-2022", "31-5-2022", "6-6-2022", "13-6-2022", "20-6-2022", "27-6-2022", "5-7-2022", "11-7-2022", "18-7-2022", "25-7-2022", "1-8-2022", "8-8-2022", "15-8-2022","22-8-2022", "29-8-2022", "6-9-2022", "12-9-2022", "19-9-2022", "26-9-2022", "3-10-2022", "11-10-2022", "17-10-2022", "24-10-2022", "31-10-2022", "7-11-2022", "14-11-2022", "21-11-2022", "28-11-2022", "5-12-2022", "12-12-2022", "19-12-2022", "3-1-2023", "9-1-2023", "16-1-2023", "23-1-2023", "30-1-2023"],
    }
  },
  methods: {
    checkboxChanges(e) {
      const self = this;

      switch(this.currentPath) {
        case 'admission':
        case 'slug-admission':

          //Switch for the ids'
          switch (e.target.name) {
            case 'japan_country_trigger':
              const locFormInfos = this.formInfos;
              const arrayKey = locFormInfos.map(form => form.name == 'country').indexOf(true);

              locFormInfos[arrayKey].isShow = e.target.value == "true";
              this.formInfos = locFormInfos;
              break;
            case 'student_visa_application':
              const selected = e.target.value;

              this.resetDate('#lesson_start_date', (selected == 'Yes') ? self.admissionYesDates : self.admissionNoDates);
              break;

            default:
              break;
          }
        break;
      }
    },
    resetDate(id, allowedDates) {
      $(id).datepicker('remove');
      $(id).datepicker({
        beforeShowDay: function (date) {
          var allDates = date.getDate() + '-' + (date.getMonth() + 1) + '-' + date.getFullYear();

          if(allowedDates.indexOf(allDates) != -1)
            return true;
          else
            return false;
        }
      });
    },
    getFormData() {
      this.formInfos.filter(forminfo => forminfo.type == 'datepicker')
                    .map(forminfo => {
                      this.formdata[forminfo.name] = $(`#${forminfo.name}`).datepicker('getFormattedDate');
                    });

      return this.formdata;
    }
  },
  mounted() {
    $(".date").datepicker({
      autoclose: true,
      todayHighlight: true
    }).datepicker('update', new Date());

    switch(this.currentPath) {
      case 'admission':
      case 'slug-admission':
        this.resetDate('#lesson_start_date', this.admissionYesDates);
      break;
      case 'freetrial':
      case 'slug-freetrial':
        $("#date_schedule").datepicker('remove');
        $("#date_schedule").datepicker({
          daysOfWeekDisabled: [0, 1, 5, 6]
        });
        break;
    }
  },
  created() {
    this.currentPath = this.$route.name;
  }
}
